class Rectangle:
    def __init__(self, width, height):
        self.width = width
        self.height = height

    def area(self):
        return self.width * self.height

    def perimeter(self):
        return 2 * (self.width + self.height)


def rect_info(width, height):
    r = Rectangle(width, height)
    return [r.area(), r.perimeter()]

